insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('chair-squat','Chair Squat','lower_body','Sit down to a sturdy chair and stand back up with control. It trains the movement you use every day.',array['Quadriceps','Glutes']::text[],array['chair']::text[],1,'bodyweight',false,'Stand in front of a sturdy chair, feet about hip-width apart, toes slightly out. Arms forward or crossed.',array['Push your hips back as if about to sit.','Lower slowly until you lightly touch the seat.','Press through your whole foot to stand tall.','Squeeze your glutes at the top.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Dropping onto the chair','Knees falling inwards','Leaning far forward']::text[],array['Place the chair against a wall so it cannot slide.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['knee']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('sit-to-stand-hands','Supported Sit-to-Stand','lower_body','A gentler squat using your hands on the chair arms or thighs for help.',array['Quadriceps','Glutes']::text[],array['chair']::text[],1,'bodyweight',false,'Sit tall near the front of a sturdy chair, feet flat and hip-width apart.',array['Lean slightly forward.','Use your hands on thighs or armrests to help as needed.','Stand up fully.','Sit back slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Using momentum','Rushing the way down']::text[],array['Make sure the chair is stable.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('bodyweight-squat','Bodyweight Squat','lower_body','A full squat without a chair, building control and strength.',array['Quadriceps','Glutes','Core']::text[],'{}'::text[],2,'bodyweight',false,'Stand with feet shoulder-width apart, toes slightly out, chest proud.',array['Push hips back and bend your knees.','Lower until thighs are near parallel, or as far as is comfortable.','Press through your feet to stand.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Heels lifting','Knees collapsing inwards','Rounding the back']::text[],array['Keep a chair behind you as a safety net.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['knee']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('goblet-squat','Goblet Squat','lower_body','A squat holding one dumbbell at your chest, which helps keep your torso upright.',array['Quadriceps','Glutes','Core']::text[],array['dumbbells']::text[],3,'dumbbell',false,'Hold one dumbbell vertically against your chest with both hands. Feet shoulder-width apart.',array['Brace your tummy gently.','Squat down between your knees.','Keep the weight close to your chest.','Stand tall.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Letting the dumbbell drift forward','Rounding the back']::text[],array['Start very light.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['knee','back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('supported-low-step-up','Supported Low Step-Up','lower_body','Step onto a low step while holding a wall or chair for balance.',array['Quadriceps','Glutes','Balance']::text[],array['step']::text[],2,'bodyweight',true,'Stand facing a low, stable step. Rest one hand lightly on a wall or chair back.',array['Place your whole foot on the step.','Press through that heel to stand up.','Lower the other foot back slowly.','Complete all reps, then switch legs.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Pushing off the back foot','Leaning heavily on the support']::text[],array['Use a low, non-slip step.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,2,60,array['knee','balance']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('step-up','Step-Up','lower_body','A step-up with little or no hand support; add light dumbbells when ready.',array['Quadriceps','Glutes','Balance']::text[],array['step']::text[],3,'dumbbell',true,'Stand facing a stable step, dumbbells (if used) by your sides.',array['Step up with control.','Stand tall on top.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Rushing','Using momentum']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,2,60,array['knee','balance']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('split-squat-supported','Supported Split Squat','lower_body','A small lunge position holding a chair for balance.',array['Quadriceps','Glutes']::text[],array['chair']::text[],2,'bodyweight',true,'Hold a chair back. Step one foot back into a staggered stance.',array['Bend both knees to lower a short way.','Keep your torso upright.','Press up through the front foot.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Stance too short','Front knee drifting in']::text[],array['Only lower as far as is comfortable.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,2,60,array['knee']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('calf-raise-supported','Supported Calf Raise','lower_body','Rise onto your toes holding a counter or chair. Great for walking and balance.',array['Calves']::text[],'{}'::text[],1,'bodyweight',false,'Stand tall holding a counter or chair back, feet hip-width apart.',array['Rise slowly onto the balls of your feet.','Pause briefly at the top.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Bouncing','Rolling the ankles outwards']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],10,15,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('single-leg-calf-raise','Single-Leg Calf Raise','lower_body','A calf raise on one leg with light fingertip support.',array['Calves','Balance']::text[],'{}'::text[],3,'bodyweight',true,'Hold a counter lightly. Lift one foot slightly off the floor.',array['Rise onto the toes of the standing leg.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Leaning on the support']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['balance']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('wall-sit','Wall Sit','lower_body','Hold a gentle seated position against a wall to build leg endurance.',array['Quadriceps','Glutes']::text[],'{}'::text[],2,'timed',false,'Lean your back against a wall, feet a step forward and hip-width apart.',array['Slide down a short way – only as low as feels comfortable.','Hold, breathing steadily.','Slide back up.']::text[],'Breathe slowly and steadily throughout the hold.',array['Going too deep','Holding your breath']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],15,30,2,60,array['knee']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('wall-push-up','Wall Push-Up','upper_push','A push-up against a wall – a comfortable way to learn the movement.',array['Chest','Triceps','Shoulders']::text[],'{}'::text[],1,'bodyweight',false,'Stand an arm''s length from a wall. Hands on the wall at chest height, slightly wider than shoulders.',array['Keep your body in one straight line.','Bend your elbows and bring your chest towards the wall.','Press away until your arms are straight.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Sagging hips','Elbows flaring wide','Head poking forward']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['shoulder','wrist']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('incline-push-up','Incline Push-Up','upper_push','Hands on a sturdy surface (a chair seat or sofa edge) to make a push-up more manageable.',array['Chest','Triceps','Shoulders','Core']::text[],array['chair']::text[],2,'bodyweight',false,'Hands on the edge of a stable chair, body in a straight line, feet back.',array['Lower your chest towards the chair.','Keep elbows about 45° from your body.','Press back up.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Hips sagging','Chair sliding']::text[],array['Brace the chair against a wall.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,12,2,60,array['shoulder','wrist']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('floor-push-up','Floor Push-Up','upper_push','The classic push-up on the floor (knees down is a perfectly good option).',array['Chest','Triceps','Shoulders','Core']::text[],array['mat']::text[],3,'bodyweight',false,'Hands under shoulders on a mat, body straight from head to knees or heels.',array['Lower with control.','Press back up.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Sagging hips','Shrugged shoulders']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],5,10,2,60,array['shoulder','wrist']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('seated-shoulder-press','Seated Dumbbell Shoulder Press','upper_push','Press light dumbbells overhead while seated with back support.',array['Shoulders','Triceps']::text[],array['chair','dumbbells']::text[],2,'dumbbell',false,'Sit tall on a sturdy chair with a back. Dumbbells at shoulder height, palms forward.',array['Press the dumbbells up until arms are nearly straight.','Lower slowly to shoulder height.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Arching the lower back','Shrugging','Using too heavy a weight']::text[],array['Skip if overhead movement is uncomfortable – choose the band press or lateral raise instead.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['shoulder','back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('band-shoulder-press','Band Shoulder Press','upper_push','An overhead press using a resistance band under your feet or seat.',array['Shoulders','Triceps']::text[],array['chair','bands']::text[],1,'band',false,'Sit tall; anchor the band under your feet. Hold the ends at shoulder height.',array['Press up smoothly.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Band slipping','Arching the back']::text[],array['Check the band for tears before each use.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('standing-shoulder-press','Standing Dumbbell Shoulder Press','upper_push','A standing overhead press that also challenges your core.',array['Shoulders','Triceps','Core']::text[],array['dumbbells']::text[],3,'dumbbell',false,'Stand tall, feet hip-width, dumbbells at shoulder height.',array['Tighten your tummy gently.','Press overhead.','Lower with control.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Leaning back','Locking knees']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['shoulder','back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('dumbbell-floor-press','Dumbbell Floor Press','upper_push','Press dumbbells upwards while lying on the floor; the floor limits the range to protect your shoulders.',array['Chest','Triceps']::text[],array['mat','dumbbells']::text[],2,'dumbbell',false,'Lie on a mat, knees bent, dumbbells held above your chest.',array['Lower until your upper arms lightly touch the floor.','Press back up.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Dropping the weights','Elbows flaring wide']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('lateral-raise','Lateral Raise','upper_push','Lift light dumbbells out to the sides to the height of your shoulders.',array['Shoulders']::text[],array['dumbbells']::text[],2,'dumbbell',false,'Stand or sit tall, a light dumbbell in each hand by your sides, elbows slightly bent.',array['Raise your arms out to the sides until about shoulder height.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Swinging','Going too heavy','Shrugging']::text[],array['Use very light weights.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('triceps-extension','Overhead Triceps Extension','upper_push','Straighten your elbows with one dumbbell held behind your head.',array['Triceps']::text[],array['chair','dumbbells']::text[],2,'dumbbell',false,'Sit tall, holding one dumbbell with both hands overhead (or lower it behind your head if overhead is uncomfortable).',array['Bend elbows to lower the weight behind your head.','Straighten your arms.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Elbows flaring','Arching the back']::text[],array['Skip if overhead positions are uncomfortable.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('supported-db-row','Supported Dumbbell Row','upper_pull','Rest one hand on a chair or bench and pull a dumbbell towards your hip.',array['Upper back','Biceps']::text[],array['chair','dumbbells']::text[],1,'dumbbell',true,'Stand beside a chair, one hand on the seat, a soft hinge at the hips, flat back. Dumbbell in the other hand, arm hanging.',array['Pull the dumbbell towards your hip, leading with the elbow.','Squeeze your shoulder blade gently.','Lower slowly.','Complete all reps, then switch sides.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Twisting the torso','Rushing','Shrugging the shoulder']::text[],array['Keep your back long and neutral.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('bench-row','Bench-Supported Row','upper_pull','A row with one knee and hand on a bench for stable back support.',array['Upper back','Biceps']::text[],array['bench','dumbbells']::text[],2,'dumbbell',true,'Place one knee and hand on a bench. Back flat, dumbbell hanging.',array['Row to your hip.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Twisting','Jerking the weight']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('band-row','Seated Band Row','upper_pull','Pull a resistance band towards your tummy while seated.',array['Upper back','Biceps']::text[],array['mat','bands']::text[],1,'band',false,'Sit on a mat with legs extended or knees slightly bent. Loop the band around your feet; hold the ends.',array['Sit tall.','Pull elbows back, squeezing your shoulder blades.','Return slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Rounding the back','Shrugging']::text[],array['Check the band for tears.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('dumbbell-curl','Dumbbell Bicep Curl','upper_pull','Bend your elbows to lift dumbbells towards your shoulders.',array['Biceps']::text[],array['dumbbells']::text[],1,'dumbbell',false,'Sit or stand tall, dumbbells by your sides, palms forward.',array['Keep elbows close to your sides.','Curl the weights up.','Lower slowly over about three seconds.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Swinging the body','Elbows drifting forward']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('hammer-curl','Hammer Curl','upper_pull','A curl with palms facing each other, which also works your forearms.',array['Biceps','Forearms']::text[],array['dumbbells']::text[],2,'dumbbell',false,'Stand or sit tall, dumbbells by your sides, palms facing in.',array['Curl up keeping palms facing in.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Swinging','Wrist bending']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('band-curl','Band Bicep Curl','upper_pull','A curl using a band under your feet.',array['Biceps']::text[],array['bands']::text[],1,'band',false,'Stand on the band, ends in hands, palms forward.',array['Curl up.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Swinging','Band slipping']::text[],array['Check the band for tears.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('band-pull-apart','Band Pull-Apart','upper_pull','Open a band across your chest to strengthen the muscles that support good posture.',array['Rear shoulders','Upper back']::text[],array['bands']::text[],1,'band',false,'Hold a band in front of you at chest height, hands shoulder-width apart.',array['Pull the band apart, squeezing your shoulder blades.','Return slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Shrugging','Arching the back']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],10,15,2,60,array['shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('reverse-fly','Seated Reverse Fly','upper_pull','Lean forward slightly and lift light dumbbells out to the sides for the muscles between your shoulder blades.',array['Rear shoulders','Upper back']::text[],array['chair','dumbbells']::text[],2,'dumbbell',false,'Sit near the front of a chair, hinge forward slightly with a flat back, dumbbells hanging.',array['Raise the weights out to the sides with soft elbows.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Using heavy weights','Rounding the back']::text[],array['Use very light weights.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('glute-bridge','Glute Bridge','glutes_posterior','Lift your hips from the floor to strengthen glutes and hamstrings.',array['Glutes','Hamstrings']::text[],array['mat']::text[],1,'bodyweight',false,'Lie on your back on a mat, knees bent, feet flat and hip-width apart, arms by your sides.',array['Press through your heels.','Lift your hips until shoulders, hips and knees form a line.','Squeeze your glutes, then lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Over-arching the lower back','Pushing through toes']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('loaded-glute-bridge','Loaded Glute Bridge','glutes_posterior','A bridge with a dumbbell resting on your hips.',array['Glutes','Hamstrings']::text[],array['mat','dumbbells']::text[],2,'dumbbell',false,'As for the glute bridge, with a dumbbell held across your hips.',array['Lift hips, keeping the weight steady.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Arching the back','Dumbbell rolling']::text[],array['Use a folded towel under the weight for comfort.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('single-leg-bridge','Single-Leg Glute Bridge','glutes_posterior','A bridge on one leg for extra challenge.',array['Glutes','Hamstrings','Core']::text[],array['mat']::text[],3,'bodyweight',true,'As for the glute bridge, with one leg extended.',array['Lift with the standing foot.','Keep your hips level.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Hips twisting','Arching']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('dumbbell-rdl','Light Dumbbell Romanian Deadlift','glutes_posterior','Hinge forward at the hips with dumbbells sliding down your thighs.',array['Hamstrings','Glutes','Lower back']::text[],array['dumbbells']::text[],2,'dumbbell',false,'Stand tall, feet hip-width apart, dumbbells in front of your thighs.',array['Push your hips back, keeping knees softly bent.','Slide the weights down your thighs with a long, flat back.','Stop when you feel a stretch in the back of your legs.','Squeeze your glutes to stand.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Rounding the back','Squatting instead of hinging','Going too low']::text[],array['Go only as low as you can keep a flat back.','Use light weights first.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('hip-hinge','Hip Hinge (Bodyweight)','glutes_posterior','Practise the hinge pattern with no weight, hands on your hips.',array['Hamstrings','Glutes']::text[],'{}'::text[],1,'bodyweight',false,'Stand tall, feet hip-width apart, hands on hips.',array['Push hips back, knees softly bent.','Tip forward with a flat back.','Squeeze your glutes to stand.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Rounding','Knees bending too much']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('clamshell','Clamshell','glutes_posterior','Lying on your side, open your top knee to strengthen the outer hip.',array['Outer glutes','Hip stabilisers']::text[],array['mat']::text[],1,'bodyweight',true,'Lie on your side on a mat, knees bent, feet together, head supported.',array['Keep feet together.','Lift your top knee without rolling back.','Lower slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Rolling backwards','Rushing']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],10,15,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('band-side-step','Banded Side Step','glutes_posterior','Step sideways with a band around your thighs.',array['Outer glutes','Hip stabilisers']::text[],array['bands']::text[],2,'band',false,'Band just above your knees, knees slightly bent, hold a counter if needed.',array['Step sideways with control.','Keep tension on the band.','Return the same way.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Leaning','Letting the band snap']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,array['balance','knee']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('dead-bug','Dead Bug','core','Lying on your back, move opposite arm and leg while keeping your tummy steady.',array['Deep core']::text[],array['mat']::text[],1,'bodyweight',false,'Lie on your back, arms up towards the ceiling, hips and knees bent at 90°.',array['Gently press your lower back towards the floor.','Lower opposite arm and leg slowly.','Return and switch sides.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Lower back arching','Moving too fast']::text[],array['Make the range smaller if your back lifts.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,2,60,array['back']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('marching-bridge-hold','Gentle Core Brace','core','Lie with knees bent and practise gently tightening your deep tummy muscles while breathing.',array['Deep core']::text[],array['mat']::text[],1,'bodyweight',false,'Lie on your back, knees bent, feet flat.',array['Breathe in.','As you breathe out, gently draw your belly button towards your spine.','Hold for 3 breaths.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Holding your breath','Squeezing too hard']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('bird-dog','Bird Dog','core','On hands and knees, extend opposite arm and leg to train core and back stability.',array['Core','Back stabilisers','Glutes']::text[],array['mat']::text[],2,'bodyweight',false,'On hands and knees, hands under shoulders, knees under hips, back flat.',array['Extend one leg back and the opposite arm forward.','Keep your hips level.','Pause, then return and switch sides.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Arching the back','Hips tilting','Rushing']::text[],array['Pad your knees with a folded mat if needed.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,2,60,array['wrist','back','shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('wall-plank','Wall Plank','core','A standing plank leaning into a wall.',array['Core','Shoulders']::text[],'{}'::text[],1,'timed',false,'Place forearms on a wall, body leaning in a straight line.',array['Tighten your tummy and glutes gently.','Hold, breathing steadily.']::text[],'Breathe steadily; don''t hold your breath.',array['Sagging hips']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],15,30,2,60,array['shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('incline-plank','Incline Plank','core','A plank with forearms on a sturdy chair.',array['Core','Shoulders']::text[],array['chair']::text[],2,'timed',false,'Forearms on a braced chair seat, body in a straight line.',array['Tighten tummy and glutes.','Hold.']::text[],'Breathe steadily.',array['Hips sagging or piking']::text[],array['Brace the chair against a wall.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],15,30,2,60,array['shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('pallof-press','Band Pallof Press','core','Press a band away from your chest while resisting rotation.',array['Core','Obliques']::text[],array['bands']::text[],2,'band',true,'Anchor a band at chest height to a sturdy door anchor or post; stand side-on, hands at your chest.',array['Press hands straight out.','Resist the band twisting you.','Return slowly.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Twisting','Leaning away']::text[],array['Use a secure anchor.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,60,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('side-plank-knee','Side Plank (Knees Bent)','core','Hold your body in a line on your forearm, knees bent.',array['Obliques','Hip stabilisers']::text[],array['mat']::text[],2,'timed',true,'Lie on your side on a mat, forearm under shoulder, knees bent.',array['Lift your hips.','Hold.','Switch sides.']::text[],'Breathe steadily.',array['Hips dropping','Shoulder shrugging']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],10,25,2,60,array['shoulder']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('single-leg-stand','Single-Leg Stand','balance','Balance on one leg next to a counter for safety.',array['Hip stabilisers','Ankles']::text[],'{}'::text[],1,'timed',true,'Stand beside a counter with fingertips resting on it.',array['Lift one foot a few centimetres.','Hold steady.','Lower and switch.']::text[],'Breathe normally.',array['Gripping the support']::text[],array['Always keep a stable support within reach.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],10,30,2,30,array['balance']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('tandem-stand','Tandem Stand','balance','Stand with one foot directly in front of the other.',array['Ankles','Core']::text[],'{}'::text[],1,'timed',false,'Stand beside a counter, one foot directly in front of the other, heel to toe.',array['Hold the position.','Switch feet.']::text[],'Breathe normally.',array['Holding the support tightly']::text[],array['Keep support within reach.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],15,30,2,30,array['balance']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('heel-to-toe-walk','Heel-to-Toe Walk','balance','Walk in a straight line placing each heel directly in front of the opposite toes.',array['Ankles','Core']::text[],'{}'::text[],2,'bodyweight',false,'Stand beside a wall or counter at the start of a clear path.',array['Step heel-to-toe.','Look ahead.','Walk about 10 steps and return.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Looking down','Rushing']::text[],array['Keep a wall within reach.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],8,12,2,30,array['balance']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('cat-cow','Cat–Cow','mobility','Gently move your spine between rounded and arched positions.',array['Spine','Core']::text[],array['mat']::text[],1,'bodyweight',false,'On hands and knees on a mat.',array['Breathe in and gently lift your chest and tailbone.','Breathe out and round your back.','Move slowly and comfortably.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Moving too far or fast']::text[],array['Stay within a comfortable range.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,1,20,array['wrist']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('thoracic-rotation','Seated Upper-Back Rotation','mobility','Gently twist your upper back while seated.',array['Upper back']::text[],array['chair']::text[],1,'bodyweight',false,'Sit tall on a chair, arms crossed over your chest.',array['Turn your upper body to one side.','Return to centre and turn the other way.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Twisting from the lower back']::text[],array['Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,1,20,'{}'::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('hip-flexor-stretch','Kneeling Hip Flexor Stretch','mobility','A gentle stretch for the front of the hip.',array['Hip flexors']::text[],array['mat']::text[],1,'timed',true,'Half-kneel on a mat with a chair or wall nearby for support.',array['Tuck your tailbone under.','Gently shift forward until you feel a stretch.','Hold, then switch.']::text[],'Breathe slowly.',array['Arching the back']::text[],array['Pad your knee if needed.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],20,30,1,15,array['knee']::text[]) on conflict (id) do nothing;
insert into public.exercise_library (id,name,category,description,muscles,requires,difficulty,load_type,per_side,starting_position,steps,breathing,common_mistakes,safety_notes,rep_min,rep_max,sets,rest_seconds,cautions) values ('shoulder-rolls','Shoulder Rolls and Arm Circles','mobility','A gentle warm-up for shoulders and neck.',array['Shoulders','Upper back']::text[],'{}'::text[],1,'bodyweight',false,'Stand or sit tall.',array['Roll your shoulders backwards slowly.','Reach arms out and make small circles.']::text[],'Breathe out as you make the effort and in as you return. Never hold your breath.',array['Rushing']::text[],array['Skip anything that pinches.','Stop and rest if you feel sharp, pinching or unusual pain.']::text[],6,10,1,15,'{}'::text[]) on conflict (id) do nothing;
